constexpr double kWindowSeconds = 24;
constexpr double kHopSeconds = 8;
constexpr double kHistogramSeconds = 0.002;
constexpr double kPulseWidthSeconds = 0.020;
constexpr std::array<size_t, 3> kBands{0, 2, 3};
constexpr std::array<double, 3> kBandWeights{0.50, 0.35, 0.15};
constexpr std::array<double, 7> kRatios{0.5, 2.0 / 3, 0.75, 1, 4.0 / 3, 1.5, 2};

struct PreparedBand {
    std::vector<BeatClockEvent> events;
    double totalWeight = 0;
};

struct Window {
    double start;
    double center;
    std::array<PreparedBand, kBands.size()> bands;
};

double quantile(std::vector<double> values, double fraction) {
    if (values.empty()) {
        return 0;
    }
    std::sort(values.begin(), values.end());
    const double index = fraction * (values.size() - 1);
    const size_t lower = static_cast<size_t>(index);
    const size_t upper = std::min(lower + 1, values.size() - 1);
    return values[lower] + (values[upper] - values[lower]) * (index - lower);
}

double weightedQuantile(const std::vector<double>& values,
        const std::vector<double>& weights,
        double fraction) {
    std::vector<std::pair<double, double>> sorted;
    double total = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        sorted.emplace_back(values[i], weights[i]);
        total += weights[i];
    }
    std::sort(sorted.begin(), sorted.end());
    const double target = total * fraction;
    double cumulative = 0;
    double previous = sorted.front().first;
    for (const auto& [value, weight] : sorted) {
        if (weight > 0 && cumulative + weight >= target) {
            return previous + (value - previous) * (target - cumulative) / weight;
        }
        cumulative += weight;
        previous = value;
    }
    return sorted.back().first;
}

double wrap(double value, double period) {
    return value - period * std::floor(value / period);
}

std::vector<Window> prepareWindows(
        const std::array<std::vector<BeatClockEvent>, 4>& input,
        double duration) {
    std::array<std::vector<BeatClockEvent>, kBands.size()> bands;
    for (size_t band = 0; band < bands.size(); ++band) {
        for (const auto& event : input[kBands[band]]) {
            if (std::isfinite(event.time) && std::isfinite(event.weight) &&
                    event.time >= 0 && event.time < duration && event.weight > 0) {
                bands[band].push_back(event);
            }
        }
        std::sort(bands[band].begin(),
                bands[band].end(),
                [](const auto& lhs, const auto& rhs) {
                    return lhs.time < rhs.time;
                });
    }
    std::vector<Window> windows;
    for (double start = 0; start < duration - kWindowSeconds; start += kHopSeconds) {
        Window window{start, start + kWindowSeconds / 2, {}};
        for (size_t band = 0; band < bands.size(); ++band) {
            auto& prepared = window.bands[band];
            std::vector<double> weights;
            for (const auto& event : bands[band]) {
                if (event.time >= start && event.time < start + kWindowSeconds) {
                    prepared.events.push_back(event);
                    weights.push_back(event.weight);
                }
            }
            const double scale = std::max(1e-12, quantile(weights, 0.8));
            for (auto& event : prepared.events) {
                event.weight = std::min(1.0, event.weight / scale);
                prepared.totalWeight += event.weight;
            }
        }
        windows.push_back(std::move(window));
    }
    return windows;
}

struct PulseSupport {
    double score = 0;
    double fullMatchedFraction = 0;
};

class PulseHistogram {
  public:
    explicit PulseHistogram(double bpm)
            : m_period(60 / bpm),
              m_count(std::clamp(static_cast<int>(std::ceil(m_period / kHistogramSeconds)),
                      8,
                      2048)) {
        m_count += m_count % 2;
        m_width = m_period / m_count;
        const double sigma = kPulseWidthSeconds / m_width;
        const int radius = static_cast<int>(std::floor(4 * sigma + 0.5));
        double sum = 0;
        for (int i = -radius; i <= radius; ++i) {
            const double value = std::exp(-0.5 * i * i / (sigma * sigma));
            m_kernel.push_back(value);
            sum += value;
        }
        for (auto& value : m_kernel) {
            value *= sigma * std::sqrt(2 * std::acos(-1.0)) / sum;
        }
    }

    size_t count() const {
        return m_count;
    }

    double width() const {
        return m_width;
    }

    std::vector<double> measure(const PreparedBand& band) const {
        std::vector<double> histogram(m_count, 0);
        if (band.events.size() < 8) {
            return histogram;
        }
        for (const auto& event : band.events) {
            const auto bin = std::min(m_count - 1,
                    static_cast<int>(std::floor(wrap(event.time, m_period) / m_width)));
            histogram[bin] += event.weight;
        }
        const int radius = static_cast<int>(m_kernel.size() / 2);
        const double scale = 2 / (kWindowSeconds / m_period + band.totalWeight);
        std::vector<double> smoothed(m_count, 0);
        for (int bin = 0; bin < m_count; ++bin) {
            if (histogram[bin] == 0) {
                continue;
            }
            for (size_t offset = 0; offset < m_kernel.size(); ++offset) {
                const int index = (bin + static_cast<int>(offset) - radius +
                                          m_count * (1 + radius / m_count)) %
                        m_count;
                smoothed[index] += histogram[bin] * m_kernel[offset] * scale;
            }
        }
        return smoothed;
    }

    PulseSupport score(const Window& window) const {
        PulseSupport result;
        for (size_t band = 0; band < kBands.size(); ++band) {
            const auto histogram = measure(window.bands[band]);
            const double maximum = *std::max_element(histogram.begin(), histogram.end());
            result.score += kBandWeights[band] * maximum;
            if (band == kBands.size() - 1 && window.bands[band].totalWeight > 0) {
                const double total = window.bands[band].totalWeight;
                result.fullMatchedFraction =
                        maximum * (kWindowSeconds / m_period + total) / (2 * total);
            }
        }
        return result;
    }

  private:
    double m_period;
    int m_count;
    double m_width;
    std::vector<double> m_kernel;
};

struct Family {
    double ratio;
    std::vector<double> scores;
    std::vector<double> tempos;
    std::vector<double> fullMatchedFraction;
    double meanScore = 0;
};

Family measureFamily(const std::vector<Window>& windows, double seed, double ratio) {
    Family family{ratio,
            std::vector<double>(windows.size(), 0),
            std::vector<double>(windows.size(), seed),
            std::vector<double>(windows.size(), 0)};
    for (double bpm = seed * 0.99; bpm <= seed * 1.01 + 0.0001; bpm += 0.05) {
        const PulseHistogram histogram(bpm);
        for (size_t i = 0; i < windows.size(); ++i) {
            const auto support = histogram.score(windows[i]);
            if (support.score > family.scores[i]) {
                family.scores[i] = support.score;
                family.tempos[i] = bpm;
                family.fullMatchedFraction[i] = support.fullMatchedFraction;
            }
        }
    }
    return family;
}

std::vector<double> recoverCircularPhase(const std::vector<std::vector<double>>& likelihoods,
        double period) {
    const size_t count = likelihoods.front().size();
    const double cycle = period / 2;
    const double width = cycle / count;
    std::vector<std::vector<double>> transition(count, std::vector<double>(count));
    for (size_t current = 0; current < count; ++current) {
        for (size_t previous = 0; previous < count; ++previous) {
            const double delta = wrap((static_cast<double>(current) - previous) * width +
                                                 cycle / 2,
                                         cycle) -
                    cycle / 2;
            transition[current][previous] = 0.025 * delta * delta / (0.020 * 0.020);
        }
    }
    std::vector<double> costs(count);
    std::transform(likelihoods.front().begin(),
            likelihoods.front().end(),
            costs.begin(),
            [](double score) { return -score; });
    std::vector<std::vector<size_t>> backs;
    for (size_t window = 1; window < likelihoods.size(); ++window) {
        std::vector<double> next(count, std::numeric_limits<double>::infinity());
        std::vector<size_t> back(count);
        for (size_t current = 0; current < count; ++current) {
            for (size_t previous = 0; previous < count; ++previous) {
                const double cost = costs[previous] + transition[current][previous];
                if (cost < next[current]) {
                    next[current] = cost;
                    back[current] = previous;
                }
            }
            next[current] -= likelihoods[window][current];
        }
        costs = std::move(next);
        backs.push_back(std::move(back));
    }
    std::vector<size_t> states(likelihoods.size());
    states.back() = std::min_element(costs.begin(), costs.end()) - costs.begin();
    for (size_t window = states.size() - 1; window > 0; --window) {
        states[window - 1] = backs[window - 1][states[window]];
    }
    std::vector<double> phase(states.size());
    phase.front() = (states.front() + 0.5) * width;
    for (size_t window = 1; window < states.size(); ++window) {
        const double difference =
                (static_cast<double>(states[window]) - states[window - 1]) * width;
        phase[window] = phase[window - 1] + wrap(difference + cycle / 2, cycle) - cycle / 2;
    }
    return phase;
}

std::vector<double> smoothPhase(const std::vector<double>& values,
        const std::vector<double>& weights) {
    const size_t count = values.size();
    std::vector<double> robust(count, 1);
    std::vector<double> fitted(values);
    for (int pass = 0; pass < 8; ++pass) {
        std::vector<double> diagonal(count);
        std::vector<double> first(count, 0);
        std::vector<double> second(count, 0);
        std::vector<double> rhs(count);
        for (size_t i = 0; i < count; ++i) {
            diagonal[i] = weights[i] * robust[i];
            rhs[i] = diagonal[i] * values[i];
        }
        for (size_t i = 0; i + 2 < count; ++i) {
            diagonal[i] += 10;
            diagonal[i + 1] += 40;
            diagonal[i + 2] += 10;
            first[i + 1] -= 20;
            first[i + 2] -= 20;
            second[i + 2] += 10;
        }
        for (size_t i = 0; i < count; ++i) {
            if (i >= 2) {
                second[i] /= diagonal[i - 2];
            }
            if (i >= 1) {
                first[i] = (first[i] -
                                   (i >= 2 ? second[i] * diagonal[i - 2] * first[i - 1] : 0)) /
                        diagonal[i - 1];
                diagonal[i] -= first[i] * first[i] * diagonal[i - 1];
                rhs[i] -= first[i] * rhs[i - 1];
            }
            if (i >= 2) {
                diagonal[i] -= second[i] * second[i] * diagonal[i - 2];
                rhs[i] -= second[i] * rhs[i - 2];
            }
        }
        for (size_t i = 0; i < count; ++i) {
            fitted[i] = rhs[i] / diagonal[i];
        }
        for (size_t i = count; i-- > 0;) {
            if (i + 1 < count) {
                fitted[i] -= first[i + 1] * fitted[i + 1];
            }
            if (i + 2 < count) {
                fitted[i] -= second[i + 2] * fitted[i + 2];
            }
        }
        for (size_t i = 0; i < count; ++i) {
            robust[i] = std::min(1.0, 0.015 / std::max(std::abs(values[i] - fitted[i]), 1e-12));
        }
    }
    return fitted;
}

std::pair<double, double> fitLine(const std::vector<Window>& windows,
        const std::vector<double>& values,
        const std::vector<double>& weights) {
    const double total = std::accumulate(weights.begin(), weights.end(), 0.0);
    double center = 0;
    double mean = 0;
    for (size_t i = 0; i < windows.size(); ++i) {
        center += windows[i].center * weights[i] / total;
        mean += values[i] * weights[i] / total;
    }
    double covariance = 0;
    double variance = 0;
    for (size_t i = 0; i < windows.size(); ++i) {
        covariance += weights[i] * (windows[i].center - center) * (values[i] - mean);
        variance += weights[i] * (windows[i].center - center) * (windows[i].center - center);
    }
    const double slope = variance > 0 ? covariance / variance : 0;
    return {mean - slope * center, slope};
}

double interpolatePhase(const std::vector<Window>& windows,
        const std::vector<double>& phase,
        double time) {
    size_t left = 0;
    if (time >= windows.back().center) {
        left = windows.size() - 2;
    } else if (time > windows.front().center) {
        left = static_cast<size_t>((time - windows.front().center) / kHopSeconds);
        left = std::min(left, windows.size() - 2);
    }
    const double fraction = (time - windows[left].center) / kHopSeconds;
    return phase[left] + fraction * (phase[left + 1] - phase[left]);
}

struct BandClock {
    std::vector<double> phase;
    std::vector<double> weights;
    std::vector<double> errors;
    std::vector<bool> reliable;
    double intercept;
    double slope;
};

std::optional<BandClock> recoverBand(const std::vector<Window>& windows,
        const PulseHistogram& histogram,
        size_t band,
        double period,
        double duration) {
    std::vector<std::vector<double>> likelihoods;
    std::vector<double> weights;
    std::vector<bool> reliable;
    bool firstHalf = false;
    bool secondHalf = false;
    for (const auto& window : windows) {
        const auto measured = histogram.measure(window.bands[band]);
        std::vector<double> folded(measured.size() / 2);
        for (size_t i = 0; i < folded.size(); ++i) {
            folded[i] = std::max(measured[i], measured[i + folded.size()]);
        }
        const double maximum = *std::max_element(folded.begin(), folded.end());
        const double contrast = maximum - quantile(folded, 0.5);
        const bool valid = maximum >= 0.30 && contrast >= 0.10;
        reliable.push_back(valid);
        firstHalf |= valid && window.center < duration / 2;
        secondHalf |= valid && window.center >= duration / 2;
        weights.push_back(std::pow(std::max(0.005, contrast - 0.04), 2) * (valid ? 1 : 0.1));
        likelihoods.push_back(std::move(folded));
    }
    if (std::count(reliable.begin(), reliable.end(), true) < 4 || !firstHalf || !secondHalf) {
        return std::nullopt;
    }
    const double median = std::max(1e-12, quantile(weights, 0.5));
    for (auto& weight : weights) {
        weight /= median;
    }
    const auto rawPhase = recoverCircularPhase(likelihoods, period);
    const auto phase = smoothPhase(rawPhase, weights);
    std::vector<double> errors;
    auto lineWeights = weights;
    for (size_t i = 0; i < weights.size(); ++i) {
        errors.push_back(std::abs(rawPhase[i] - phase[i]));
        lineWeights[i] *= std::min(1.0, 0.015 / std::max(errors[i], 1e-12));
    }
    const auto [intercept, slope] = fitLine(windows, phase, lineWeights);
    if (!std::isfinite(slope) || std::abs(slope) > 0.02) {
        return std::nullopt;
    }
    return BandClock{phase, weights, errors, reliable, intercept, slope};
}

struct ConsensusClock {
    std::vector<double> phase;
    double intercept;
    double slope;
    double span;
    double threshold;
    double correlation;
    double coverage;
};

std::optional<ConsensusClock> correlateClocks(const std::vector<Window>& windows,
        const BandClock& first,
        const BandClock& second,
        double duration) {
    std::vector<double> weights(windows.size());
    size_t reliableCount = 0;
    double earliest = duration;
    double latest = 0;
    for (size_t i = 0; i < windows.size(); ++i) {
        if (first.reliable[i] && second.reliable[i]) {
            weights[i] = std::sqrt(first.weights[i] * second.weights[i]);
            ++reliableCount;
            earliest = std::min(earliest, windows[i].center);
            latest = std::max(latest, windows[i].center);
        }
    }
    if (reliableCount < 4 || latest - earliest < duration / 2) {
        return std::nullopt;
    }
    const auto [firstIntercept, firstSlope] = fitLine(windows, first.phase, weights);
    const auto [secondIntercept, secondSlope] = fitLine(windows, second.phase, weights);
    std::vector<double> residuals;
    std::vector<double> phase;
    double covariance = 0;
    double firstVariance = 0;
    double secondVariance = 0;
    const double slope = (firstSlope + secondSlope) / 2;
    for (size_t i = 0; i < windows.size(); ++i) {
        const double firstResidual =
                first.phase[i] - firstIntercept - firstSlope * windows[i].center;
        const double secondResidual =
                second.phase[i] - secondIntercept - secondSlope * windows[i].center;
        const double residual = (firstResidual + secondResidual) / 2;
        covariance += weights[i] * firstResidual * secondResidual;
        firstVariance += weights[i] * firstResidual * firstResidual;
        secondVariance += weights[i] * secondResidual * secondResidual;
        residuals.push_back(residual);
        phase.push_back(firstIntercept + slope * windows[i].center + residual);
    }
    const double span = weightedQuantile(residuals, weights, 0.95) -
            weightedQuantile(residuals, weights, 0.05);
    const double noise = std::max(weightedQuantile(first.errors, weights, 0.75),
            weightedQuantile(second.errors, weights, 0.75));
    const double correlation =
            covariance / std::sqrt(std::max(1e-24, firstVariance * secondVariance));
    return ConsensusClock{phase,
            firstIntercept,
            slope,
            span,
            std::max(0.012, 3 * noise),
            correlation,
            static_cast<double>(reliableCount) / windows.size()};
}

std::optional<ConsensusClock> recoverConsensus(const std::vector<Window>& windows,
        const PulseHistogram& histogram,
        double period,
        double duration) {
    std::array<std::optional<BandClock>, kBands.size()> clocks;
    for (size_t band = 0; band < clocks.size(); ++band) {
        clocks[band] = recoverBand(windows, histogram, band, period, duration);
    }
    if (clocks[2]) {
        for (const size_t band : {size_t(1), size_t(0)}) {
            if (clocks[band]) {
                auto consensus = correlateClocks(windows, *clocks[band], *clocks[2], duration);
                if (consensus) {
                    return consensus;
                }
            }
        }
    } else if (clocks[0] && clocks[1]) {
        return correlateClocks(windows, *clocks[0], *clocks[1], duration);
    }
    return std::nullopt;
}

