std::optional<RecoveredBeatClock> recoverBeatClock(
        const std::array<std::vector<BeatClockEvent>, 4>& events,
        double referenceBpm,
        double duration,
        const std::array<std::vector<BeatClockEvent>, 4>* attacks) {
    if (!std::isfinite(referenceBpm) || referenceBpm < 15 || referenceBpm > 400 ||
            !std::isfinite(duration) || duration < 48) {
        return std::nullopt;
    }
    const auto windows = prepareWindows(events, duration);
    if (windows.size() < 4) {
        return std::nullopt;
    }
    std::vector<Family> families;
    size_t reference = 0;
    for (double ratio : kRatios) {
        if (ratio == 1) {
            reference = families.size();
        }
        families.push_back(measureFamily(windows, referenceBpm * ratio, ratio));
    }
    std::vector<double> weights(windows.size());
    for (size_t window = 0; window < windows.size(); ++window) {
        double best = 0;
        for (const auto& family : families) {
            best = std::max(best, family.scores[window]);
        }
        weights[window] = std::max(0.002, std::pow(std::max(0.0, best - 0.20), 2));
    }
    const double totalWeight = std::accumulate(weights.begin(), weights.end(), 0.0);
    for (auto& family : families) {
        family.meanScore = std::inner_product(family.scores.begin(),
                                   family.scores.end(),
                                   weights.begin(),
                                   0.0) /
                totalWeight;
    }
    size_t selected = reference;
    double bestUtility = families[reference].meanScore;
    for (size_t candidate = 0; candidate < families.size(); ++candidate) {
        const auto& family = families[candidate];
        if (candidate == reference) {
            continue;
        }
        const double cost = 0.055 + 0.04 * std::abs(std::log2(family.ratio));
        double dominance = 0;
        double corroboration = 0;
        for (size_t window = 0; window < windows.size(); ++window) {
            if (family.scores[window] > families[reference].scores[window] + 0.04) {
                dominance += weights[window] / totalWeight;
            }
            // Normalize by event mass so fewer expected beats cannot alone justify sparse kicks.
            if (family.fullMatchedFraction[window] + 0.01 >=
                    families[reference].fullMatchedFraction[window]) {
                corroboration += weights[window] / totalWeight;
            }
        }
        const double utility = family.meanScore - cost;
        if (dominance > 0.55 && corroboration > 0.55 && utility > bestUtility) {
            bestUtility = utility;
            selected = candidate;
        }
    }
    const auto& family = families[selected];
    if (family.meanScore < 0.30) {
        return std::nullopt;
    }
    const double bpm = weightedQuantile(family.tempos, weights, 0.5);
    const double period = 60 / bpm;
    const PulseHistogram histogram(bpm);
    auto consensus = attacks
            ? recoverConsensus(prepareWindows(*attacks, duration), histogram, period, duration)
            : std::nullopt;
    if (!consensus) {
        consensus = recoverConsensus(windows, histogram, period, duration);
    }
    if (!consensus) {
        return std::nullopt;
    }
    auto phase = consensus->phase;
    const double intercept = consensus->intercept;
    const double slope = consensus->slope;
    const double fittedBpm = bpm * (1 - slope);
    const bool coherent = consensus->correlation > 0.6;
    if (!coherent) {
        for (size_t i = 0; i < windows.size(); ++i) {
            phase[i] = intercept + slope * windows[i].center;
        }
    }
    RecoveredBeatClock result{fittedBpm,
            wrap(intercept / (1 - slope), 60 / fittedBpm),
            consensus->span <= consensus->threshold || !coherent,
            family.ratio,
            consensus->span,
            family.meanScore * consensus->coverage,
            {}};
    const auto first = static_cast<long long>(
            std::ceil(-interpolatePhase(windows, phase, 0) / period));
    const auto last = static_cast<long long>(std::floor(
            (duration - interpolatePhase(windows, phase, duration)) / period));
    for (auto index = first; index <= last; ++index) {
        double time = (index * period + intercept) / (1 - slope);
        for (int pass = 0; pass < 6; ++pass) {
            time = index * period + interpolatePhase(windows, phase, time);
        }
        if (time >= 0 && time < duration) {
            if (!result.beatTimes.empty() && time <= result.beatTimes.back()) {
                return std::nullopt;
            }
            result.beatTimes.push_back(time);
        }
    }
    return result;
}

